module calculator(
  input [7:0] num1,
  input [7:0] num2,
  input [1:0] op,
  output reg [7:0] result
);

always @(*)
begin
  case(op)
    2'b00: result = num1 + num2;
    2'b01: result = num1 - num2;
    2'b10: result = num1 * num2;
    2'b11: result = num1 / num2;
  endcase
end

endmodule

sva:
module calculator_sva (
    input logic       clk,
    input logic [7:0] num1,
    input logic [7:0] num2,
    input logic [1:0] op,
    input logic [7:0] result
);

// Opcode 00 produces the low 8 bits of the sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ({1'b0, result} == (({1'b0, num1} + {1'b0, num2}) & 9'h0ff))
    );

// Opcode 01 produces the low 8 bits of the difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ({1'b0, result} == (({1'b0, num1} - {1'b0, num2}) & 9'h0ff))
    );

endmodule

