rtl:
module and4 (
    input A,
    input B,
    input C,
    input D,
    output X
);

    // Local signals
    wire and0_out;
    wire and1_out;
    wire and2_out;

    // AND gates
    and and0 (and0_out, A, B);
    and and1 (and1_out, C, D);

    // 2-input AND gate
    and and2 (X, and0_out, and1_out);

endmodule

sva:
module and4_sva (
    input logic clk,     // Sampling clock for assertions (DUT has no clock)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic and0_out,
    input logic and1_out
);

// DUT has no reset; purely combinational 4-input AND built from 2-input ANDs.

    // and0_out must be 1 when both A and B are 1.
    check_and0_high_when_A_and_B_high: assert property (
        @(posedge clk) (A && B) |-> (and0_out == 1'b1)
    );

// and0_out must be 0 when either A or B is 0.
    check_and0_low_when_A_or_B_low: assert property (
        @(posedge clk) ((!A) || (!B)) |-> (and0_out == 1'b0)
    );

// and1_out must be 1 when both C and D are 1.
    check_and1_high_when_C_and_D_high: assert property (
        @(posedge clk) (C && D) |-> (and1_out == 1'b1)
    );

// and1_out must be 0 when either C or D is 0.
    check_and1_low_when_C_or_D_low: assert property (
        @(posedge clk) ((!C) || (!D)) |-> (and1_out == 1'b0)
    );

// X must be 1 when both sub-AND outputs are 1.
    check_X_high_when_subands_high: assert property (
        @(posedge clk) (and0_out && and1_out) |-> (X == 1'b1)
    );

// X must be 0 when either sub-AND output is 0.
    check_X_low_when_any_suband_low: assert property (
        @(posedge clk) ((!and0_out) || (!and1_out)) |-> (X == 1'b0)
    );

// X must be 1 when all four inputs are 1.
    check_X_high_when_all_inputs_high: assert property (
        @(posedge clk) (A && B && C && D) |-> (X == 1'b1)
    );

// X must be 0 when any input is 0.
    check_X_low_when_any_input_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C) || (!D)) |-> (X == 1'b0)
    );

// and0_out being 1 implies both A and B are 1.
    check_and0_high_implies_A_and_B_high: assert property (
        @(posedge clk) and0_out |-> (A && B)
    );

// and1_out being 1 implies both C and D are 1.
    check_and1_high_implies_C_and_D_high: assert property (
        @(posedge clk) and1_out |-> (C && D)
    );

endmodule

rtl:
module xor_gate(
    input a,
    input b,
    output out_comb
);

    assign out_comb = (a & ~b) | (~a & b);

endmodule

sva:
module xor_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic out_comb
);

// Combinational DUT with no clock/reset; assertions sampled on clk.

    // Output equals RTL XOR expression.
    check_xor_equation: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// Output matches XOR operator directly.
    check_xor_operator_equiv: assert property (
        @(posedge clk) out_comb == (a ^ b)
    );

// Truth table: a=0, b=0 -> out=0.
    check_tt_00: assert property (
        @(posedge clk) (!a && !b) |-> (out_comb == 1'b0)
    );

// Truth table: a=1, b=0 -> out=1.
    check_tt_10: assert property (
        @(posedge clk) (a && !b) |-> (out_comb == 1'b1)
    );

// Truth table: a=0, b=1 -> out=1.
    check_tt_01: assert property (
        @(posedge clk) (!a && b) |-> (out_comb == 1'b1)
    );

// Truth table: a=1, b=1 -> out=0.
    check_tt_11: assert property (
        @(posedge clk) (a && b) |-> (out_comb == 1'b0)
    );

// Output low when inputs are equal.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

// Output high when inputs differ.
    check_diff_inputs_one: assert property (
        @(posedge clk) (a != b) |-> (out_comb == 1'b1)
    );

// Commutative form equivalence.
    check_commutative_form: assert property (
        @(posedge clk) out_comb == ((b & ~a) | (~b & a))
    );

endmodule

rtl:
module bin2gray(
  input [3:0] binary,
  output reg [3:0] gray
);

  always @ (binary) begin
    gray[3] = binary[3];
    gray[2] = binary[3] ^ binary[2];
    gray[1] = binary[2] ^ binary[1];
    gray[0] = binary[1] ^ binary[0];
  end

endmodule

sva:
module bin2gray_sva (
    input  logic        clk,
    input  logic [3:0]  binary,
    input  logic [3:0]  gray
);

///// Functional mapping /////
    // MSB mapping: gray[3] equals binary[3].
    check_gray_bit3_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[3] === binary[3]
    );

// gray[2] is binary[3] XOR binary[2].
    check_gray_bit2_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[2] === (binary[3] ^ binary[2])
    );

// gray[1] is binary[2] XOR binary[1].
    check_gray_bit1_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[1] === (binary[2] ^ binary[1])
    );

// gray[0] is binary[1] XOR binary[0].
    check_gray_bit0_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray[0] === (binary[1] ^ binary[0])
    );

// Full vector mapping matches {b3, b3^b2, b2^b1, b1^b0}.
    check_gray_full_mapping: assert property (
        @(posedge clk) disable iff (1'b0) gray === {binary[3], (binary[3]^binary[2]), (binary[2]^binary[1]), (binary[1]^binary[0])}
    );

endmodule

rtl:
module alu_16bit(A, B, op, Y);

  input [15:0] A, B;
  input [3:0] op;
  output [15:0] Y;

  wire [15:0] notA, notB, shiftLeft, shiftRight, rotateLeft, rotateRight;

  assign notA = ~A;
  assign notB = ~B;
  assign shiftLeft = {A[14:0], 1'b0};
  assign shiftRight = {1'b0, A[15:1]};
  assign rotateLeft = {A[14:0], A[15]};
  assign rotateRight = {A[0], A[15:1]};

  reg [15:0] Y;

  always @(*) begin
    case (op)
      4'b0000: Y = A + B;
      4'b0001: Y = A - B;
      4'b0010: Y = A & B;
      4'b0011: Y = A | B;
      4'b0100: Y = A ^ B;
      4'b0101: Y = notA;
      4'b0110: Y = shiftLeft;
      4'b0111: Y = shiftRight;
      4'b1000: Y = rotateLeft;
      4'b1001: Y = rotateRight;
      default: Y = 16'b0;
    endcase
  end

endmodule

sva:
module alu_16bit_sva (
    input logic clk,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic [3:0] op,
    input logic [15:0] Y
);

// op=0000: Y equals A + B
    check_add: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0000) |-> (Y == A + B)
    );

// op=0001: Y equals A - B
    check_sub: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0001) |-> (Y == A - B)
    );

// op=0010: Y equals A & B
    check_and: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0010) |-> (Y == (A & B))
    );

// op=0011: Y equals A | B
    check_or: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0011) |-> (Y == (A | B))
    );

// op=0100: Y equals A ^ B
    check_xor: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// op=0101: Y equals bitwise NOT of A
    check_notA: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0101) |-> (Y == ~A)
    );

// op=0110: Y equals A shifted left by 1 with LSB=0
    check_shift_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0110) |-> (Y == {A[14:0], 1'b0})
    );

// op=0111: Y equals A shifted right by 1 with MSB=0
    check_shift_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b0111) |-> (Y == {1'b0, A[15:1]})
    );

// op=1000: Y equals A rotated left by 1
    check_rotate_left: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1000) |-> (Y == {A[14:0], A[15]})
    );

// op=1001: Y equals A rotated right by 1
    check_rotate_right: assert property (
        @(posedge clk) disable iff (1'b0) (op == 4'b1001) |-> (Y == {A[0], A[15:1]})
    );

// Default case: Y is zero for unimplemented opcodes (1010..1111)
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) (op inside {[4'hA:4'hF]}) |-> (Y == 16'b0)
    );

endmodule

rtl:
module xor_inv_multiplexer (
    input clk,
    input [3:0] a,
    input [3:0] b,
    input sel_b1,
    input sel_b2,
    input sel_out,
    output reg out_always,
    output [3:0] out_xor,
    output [3:0] out_xor_inv,
    output out_logical_inv
);

    // Intermediate wires to store the selected input
    wire [3:0] selected_input_b1;
    wire [3:0] selected_input_b2;

    // 2-to-1 multiplexer to select between a and b
    assign selected_input_b1 = sel_b1 ? b : a;

    // 2-to-1 multiplexer to select between selected_input_b1 and b
    assign selected_input_b2 = sel_b2 ? b : selected_input_b1;

    // XOR and inverter operations on the selected input
    assign out_xor = selected_input_b2 ^ a;
    assign out_xor_inv = ~out_xor;
    assign out_logical_inv = !out_xor;

    // 2-to-1 multiplexer to select between XOR and logical inverse outputs
    always @(posedge clk) begin
        if (sel_out) begin
            out_always <= out_logical_inv;
        end else begin
            out_always <= out_xor_inv;
        end
    end

endmodule

sva:
module xor_inv_multiplexer_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic sel_b1,
    input logic sel_b2,
    input logic sel_out,
    input logic out_always,
    input logic [3:0] out_xor,
    input logic [3:0] out_xor_inv,
    input logic out_logical_inv
);

// out_xor equals (sel_b2 ? b : (sel_b1 ? b : a)) XOR a.
    check_out_xor_from_mux: assert property (
        @(posedge clk) out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is bitwise inverse of out_xor.
    check_out_xor_inv_is_not: assert property (
        @(posedge clk) out_xor_inv == ~out_xor
    );

// out_logical_inv is logical NOT of out_xor (NOR-reduction).
    check_out_logical_inv_is_nor: assert property (
        @(posedge clk) out_logical_inv == ~(|out_xor)
    );

// When sel_b2 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b2_drives_b_xor_a: assert property (
        @(posedge clk) sel_b2 |-> (out_xor == (b ^ a))
    );

// When sel_b2 is 0 and sel_b1 is 1, b is selected and out_xor equals b ^ a.
    check_sel_b1_drives_when_b2_low: assert property (
        @(posedge clk) (!sel_b2 && sel_b1) |-> (out_xor == (b ^ a))
    );

// When both sel_b2 and sel_b1 are 0, a is selected and out_xor is zero (a ^ a).
    check_both_selects_zero_xor_zero: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor == 4'b0000)
    );

// When both selects are 0, out_xor_inv is all ones (~0).
    check_both_selects_zero_inv_ones: assert property (
        @(posedge clk) (!sel_b2 && !sel_b1) |-> (out_xor_inv == 4'b1111)
    );

// When out_xor is zero, out_logical_inv must be 1.
    check_xor_zero_implies_logical_inv_one: assert property (
        @(posedge clk) (out_xor == 4'b0000) |-> (out_logical_inv == 1'b1)
    );

endmodule

rtl:
module mux_4to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input enable,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        2'b00: out = enable ? in0 : 4'b0;
        2'b01: out = enable ? in1 : 4'b0;
        2'b10: out = enable ? in2 : 4'b0;
        2'b11: out = enable ? in3 : 4'b0;
    endcase
end

endmodule

sva:
module mux_4to1_sva (
    input logic clk,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic enable,
    input logic [3:0] out
);

// Out matches the mux+enable function exactly.
    check_mux_function: assert property (
        @(posedge clk)
        out === (enable ? (sel == 2'b00 ? in0 :
                           sel == 2'b01 ? in1 :
                           sel == 2'b10 ? in2 : in3)
                       : 4'b0)
    );

// When disabled, out must be zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) (!enable) |-> (out === 4'b0)
    );

// When enabled and sel==00, out equals in0.
    check_sel00_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b00)) |-> (out === in0)
    );

// When enabled and sel==01, out equals in1.
    check_sel01_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b01)) |-> (out === in1)
    );

// When enabled and sel==10, out equals in2.
    check_sel10_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b10)) |-> (out === in2)
    );

// When enabled and sel==11, out equals in3.
    check_sel11_routing: assert property (
        @(posedge clk) (enable && (sel == 2'b11)) |-> (out === in3)
    );

// If all inputs are equal and enabled, out equals that common value.
    check_equal_inputs_collapse: assert property (
        @(posedge clk) (enable && (in0 === in1) && (in1 === in2) && (in2 === in3)) |-> (out === in0)
    );

// If enabled and out is zero, the selected input must be zero.
    check_zero_out_implies_zero_selected_input: assert property (
        @(posedge clk)
        (enable && (out === 4'b0)) |-> (
            (sel == 2'b00) ? (in0 === 4'b0) :
            (sel == 2'b01) ? (in1 === 4'b0) :
            (sel == 2'b10) ? (in2 === 4'b0) :
                             (in3 === 4'b0)
        )
    );

endmodule

