rtl:
module constant_generator (
  output [(1 - 1):0] op,
  input clk,
  input ce,
  input clr
);
  reg [(1 - 1):0] op_reg;

  always @(posedge clk) begin
    if (clr) begin
      op_reg <= 1'b0;
    end else if (ce) begin
      op_reg <= 1'b1;
    end
  end

  assign op = op_reg;
endmodule

sva:
module constant_generator_sva (
    input logic clk,
    input logic ce,
    input logic clr,
    input logic [(1 - 1):0] op
);

///// Reset behavior /////
    // Synchronous clear forces op low on the next cycle.
    reset_clears_op_next: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

///// Update and hold rules /////
    // With clr low, ce sets op high on the next cycle.
    ce_sets_op_high_next: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// With clr low and ce low, op holds its value.
    hold_without_ce: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// Once high and with clr low, op stays high.
    sticky_high_without_clr: assert property (
        @(posedge clk) disable iff (clr) (op == 1'b1) |=> (op == 1'b1)
    );

endmodule

rtl:
module DFF_AR (
  input CLK,
  input RST,
  input D,
  output Q,
  output QN
);

  reg Q, QN;

  always @(posedge CLK or negedge RST) begin
    if (!RST) begin
      Q <= 1'b0;
      QN <= 1'b1;
    end else begin
      Q <= D;
      QN <= ~D;
    end
  end

endmodule

sva:
module DFF_AR_sva (
  input logic CLK,
  input logic RST,   // Active-LOW asynchronous reset
  input logic D,
  input logic Q,
  input logic QN
);

///// Reset behavior /////
  // While reset is asserted low, outputs are forced to 0/1.
  reset_level_forces_values: assert property (
    @(posedge CLK) !RST |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled falling edge of reset, outputs are 0/1.
  reset_fall_forces_values: assert property (
    @(posedge CLK) $fell(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

// On a sampled rising edge of reset, outputs are still at reset values before capture.
  reset_rise_holds_reset_values_before_capture: assert property (
    @(posedge CLK) $rose(RST) |-> (Q == 1'b0 && QN == 1'b1)
  );

///// Output relationship /////
  // QN is always the logical inverse of Q.
  complement_invariant: assert property (
    @(posedge CLK) QN == ~Q
  );

// Q and QN are never both HIGH.
  never_both_high: assert property (
    @(posedge CLK) !(Q && QN)
  );

// Q and QN are never both LOW.
  never_both_low: assert property (
    @(posedge CLK) !(~Q && ~QN)
  );

// A rise on Q implies a fall on QN in the same sample.
  q_rise_implies_qn_fall: assert property (
    @(posedge CLK) $rose(Q) |-> $fell(QN)
  );

endmodule

module counter_4bit_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count
);

// Reset low forces count to zero on each clock.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (count == 4'b0000)
    );

// Next-state function when out of reset: increment on enable, else hold.
    check_next_state_function: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (count == (enable ? ($past(count) + 4'd1) : $past(count)))
    );

// When enable is 1, count increments by exactly 1 (mod 16).
    check_increment_when_enable: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable) |-> (count == ($past(count) + 4'd1))
    );

// When enable is 0, count holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && !enable) |-> (count == $past(count))
    );

// Wrap-around: from 4'hF with enable high, next value is 0.
    check_wrap_on_max: assert property (
        @(posedge clk) disable iff (!reset) ($past(reset) && enable && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

// If reset rises on a clock edge, next count is 1 if enable=1 else 0.
    check_release_from_reset_at_clk: assert property (
        @(posedge clk) $rose(reset) |-> (count == (enable ? 4'd1 : 4'd0))
    );

endmodule

rtl:
module binary_counter(
  input clk, 
  input rst, 
  output reg [3:0] count
);

  always @ (posedge clk or posedge rst) begin
    if (rst) begin
      count <= 4'b0000;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module binary_counter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

// When reset is asserted, count must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) rst |-> (count == 4'h0)
    );

// If reset is high in consecutive cycles, count holds at 0.
    check_reset_holds_zero: assert property (
        @(posedge clk) (($past(rst)===1'b1) && rst) |-> (count == 4'h0) && (count == $past(count))
    );

// Wrap-around: from 0xF to 0x0 when running.
    check_wraparound_mod16: assert property (
        @(posedge clk) disable iff (rst) (!rst && ($past(rst)===1'b0) && ($past(count) == 4'hF)) |-> (count == 4'h0)
    );

endmodule

rtl:
module control(
    input clk,
    input rst,
    input en,
    input en_mem,
    input mem_wait,
    input should_branch,
    input imm,
    output reg [8:0] control_o,
    output reg [1:0] pc_op
);

    always @(posedge clk) begin
        if (rst) begin
            control_o <= 0;
            pc_op <= 0;
        end else if (en) begin
            // Control signal generation
            control_o[0] <= en_mem;
            control_o[1] <= should_branch;
            control_o[2] <= imm;

            // Opcode signal generation
            if (imm) begin
                pc_op <= 2'b10; // Bitwise AND
            end else begin
                pc_op <= 2'b00; // Add
            end
        end
    end
endmodule

sva:
module control_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic en_mem,
    input logic mem_wait,
    input logic should_branch,
    input logic imm,
    input logic [8:0] control_o,
    input logic [1:0] pc_op
);

// Clock: clk (posedge). Reset: rst (active-high, synchronous). Logic is sequential (registered outputs).
    // Behavior: rst clears outputs; when en, control_o[2:0] reflect inputs and pc_op depends on imm; other bits hold.

    // Synchronous reset drives outputs to zero on the next cycle.
    reset_sync_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0) && (pc_op == 2'b00)
    );

// When not enabled, control_o holds its previous value.
    hold_when_en_low_control: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o))
    );

// When not enabled, pc_op holds its previous value.
    hold_when_en_low_pc: assert property (
        @(posedge clk) disable iff (rst) !en |=> (pc_op == $past(pc_op))
    );

// When enabled, upper control bits [8:3] remain unchanged.
    hi_bits_unchanged_on_en: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[8:3] == $past(control_o[8:3]))
    );

// After an enable update, pc_op[1] matches control_o[2] (both from imm).
    pc_op_msb_matches_control2_on_update: assert property (
        @(posedge clk) disable iff (rst) en |=> (pc_op[1] == control_o[2])
    );

endmodule

rtl:
module barrel_shifter (
    input [7:0] DATA,
    input [2:0] SHIFT_AMOUNT,
    input SHIFT_DIRECTION,
    output [7:0] SHIFTED_DATA
);

    reg [7:0] shifted_data;

    always @(*) begin
        if (SHIFT_DIRECTION == 0) begin
            shifted_data = DATA << SHIFT_AMOUNT;
        end else begin
            shifted_data = DATA >> SHIFT_AMOUNT;
        end
    end

    assign SHIFTED_DATA = shifted_data;

endmodule

sva:
module barrel_shifter_sva (
    input  logic        CLK,
    input  logic [7:0]  DATA,
    input  logic [2:0]  SHIFT_AMOUNT,
    input  logic        SHIFT_DIRECTION,
    input  logic [7:0]  SHIFTED_DATA
);

// For SHIFT_DIRECTION=0, output equals DATA << SHIFT_AMOUNT.
    check_left_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

// For SHIFT_DIRECTION=1, output equals DATA >> SHIFT_AMOUNT.
    check_right_shift_correct: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

// Shift amount 0 leaves data unchanged.
    check_shift_by_zero_identity: assert property (
        @(posedge CLK) (SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

// Left shift zero-fills lower bits.
    check_left_zero_fill_lsb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> ((SHIFTED_DATA & ((8'h1 << SHIFT_AMOUNT) - 8'h1)) == 8'h00)
    );

// Right shift zero-fills upper bits.
    check_right_zero_fill_msb: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> ((SHIFTED_DATA & ~(8'hFF >> SHIFT_AMOUNT)) == 8'h00)
    );

// Zero input yields zero output.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (DATA == 8'h00) |-> (SHIFTED_DATA == 8'h00)
    );

// Left shift by 7 moves bit0 to MSB and clears others.
    check_left_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {DATA[0], 7'b0})
    );

// Right shift by 7 moves MSB to LSB and clears others.
    check_right_shift_by_seven: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd7) |-> (SHIFTED_DATA == {7'b0, DATA[7]})
    );

// Output equals selected shift function for all cases.
    check_functional_equation: assert property (
        @(posedge CLK) SHIFTED_DATA == ((SHIFT_DIRECTION == 1'b0) ? (DATA << SHIFT_AMOUNT) : (DATA >> SHIFT_AMOUNT))
    );

endmodule

