    // EN low forces Y to 0.
    en_low_forces_y_zero: assert property (
        @(posedge CLK) (EN == 1'b0) |-> (Y == 1'b0)
    );

// With EN high and SEL==00, Y equals ABCD[0].
    sel_00_routes_bit0: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b00) |-> (Y == ABCD[0])
    );

// With EN high and SEL==01, Y equals ABCD[1].
    sel_01_routes_bit1: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b01) |-> (Y == ABCD[1])
    );

// With EN high and SEL==10, Y equals ABCD[2].
    sel_10_routes_bit2: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b10) |-> (Y == ABCD[2])
    );

// With EN high and SEL==11, Y equals ABCD[3].
    sel_11_routes_bit3: assert property (
        @(posedge CLK) (EN == 1'b1 && SEL == 2'b11) |-> (Y == ABCD[3])
    );

// With EN high and unknown SEL, Y drives X (default case).
    unknown_sel_drives_x_when_en: assert property (
        @(posedge CLK) (EN == 1'b1 && $isunknown(SEL)) |-> (Y === 1'bx)
    );

endmodule

rtl:
module four_bit_counter (
    // inputs:
    input clk,
    input reset,
    // outputs:
    output reg [3:0] count
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module four_bit_counter_sva (
    input logic clk,
    input logic reset,       // active-high async reset
    input logic [3:0] count  // 4-bit counter output
);

// Clock: clk (posedge). Reset: reset (active-high, asynchronous).
    // Logic: sequential with async reset; count=0 on reset, else count increments modulo 16.

    // While reset is HIGH at the clock edge, count must be 0.
    check_reset_drives_zero: assert property (
        @(posedge clk) reset |-> (count == 4'd0)
    );

// If reset is HIGH on two consecutive clock edges, count holds its value (remains 0).
    check_reset_held_stable: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == $past(count))
    );

// One cycle after reset falls at a clock edge, the counter advances to 1.
    check_first_count_after_reset_fall: assert property (
        @(posedge clk) $fell(reset) |=> (count == 4'd1)
    );

// Count is always within 4-bit range (sanity check).
    check_count_range: assert property (
        @(posedge clk) (count <= 4'd15)
    );

// Cover: observe a normal increment between consecutive cycles without reset.
    cover_normal_increment: cover property (
        @(posedge clk) disable iff (reset) (count == ($past(count) + 4'd1))
    );

// Cover: observe rollover from 15 to 0 without reset interference.
    cover_rollover: cover property (
        @(posedge clk) disable iff (reset) (count == 4'hF) ##1 (count == 4'h0)
    );

endmodule

rtl:
module barrel_shifter (
    input [15:0] in,
    input [3:0] shift,
    input dir,
    output [15:0] out
);

    assign out = (dir == 0) ? (in << shift) : (in >> shift);

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,          // Added sampling clock for SVA (RTL has no clock/reset)
    input logic [15:0] in,
    input logic [3:0]  shift,
    input logic        dir,
    input logic [15:0] out
);

// Left shift definition: dir==0 makes out = in << shift.
    check_left_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b0) |-> (out == (in << shift))
    );

// Right shift definition: dir==1 makes out = in >> shift.
    check_right_shift_definition: assert property (
        @(posedge CLK) (dir == 1'b1) |-> (out == (in >> shift))
    );

// Zero shift is identity regardless of dir.
    check_shift_zero_identity: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

// Zero input yields zero output for any dir/shift.
    check_zero_input_zero_output: assert property (
        @(posedge CLK) (in == 16'h0000) |-> (out == 16'h0000)
    );

// Left shift zero-fill: lower 'shift' bits of out are zero.
    check_left_zero_fill_lowbits: assert property (
        @(posedge CLK) (dir == 1'b0) |-> ((out & (((16'h0001 << shift) - 16'h0001))) == 16'h0000)
    );

// Right shift zero-fill: upper 'shift' bits of out are zero.
    check_right_zero_fill_highbits: assert property (
        @(posedge CLK) (dir == 1'b1) |-> ((out & (16'hFFFF << (16 - shift))) == 16'h0000)
    );

// Left shift by 15: out[14:0]==0 and out[15]==in[0].
    check_left_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd15)) |-> ((out[14:0] == 15'b0) && (out[15] == in[0]))
    );

// Right shift by 15: out[15:1]==0 and out[0]==in[15].
    check_right_shift_by_15_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd15)) |-> ((out[15:1] == 15'b0) && (out[0] == in[15]))
    );

// Left shift by 1: LSB zero and remaining bits align with in.
    check_left_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b0) && (shift == 4'd1)) |-> ((out[0] == 1'b0) && (out[15:1] == in[14:0]))
    );

// Right shift by 1: MSB zero and remaining bits align with in.
    check_right_shift_by_1_detail: assert property (
        @(posedge CLK) ((dir == 1'b1) && (shift == 4'd1)) |-> ((out[15] == 1'b0) && (out[14:0] == in[15:1]))
    );

endmodule

module r_FAULT_STATUS_sva (
    input logic clk,
    input logic reset,
    input logic wenb,
    input logic [7:0] in_data,
    input logic [7:0] reg_0x1F
);

// Synchronous reset sets reg_0x1F to zero on the next cycle.
    reset_sets_zero_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// Reset has priority over writes (wenb low) and still drives zero next cycle.
    reset_overrides_write: assert property (
        @(posedge clk) (reset && (wenb == 1'b0)) |=> (reg_0x1F == 8'h00)
    );

// When not in reset and wenb is LOW, capture in_data on the next cycle.
    write_captures_in_data: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0) |=> (reg_0x1F == $past(in_data))
    );

// When not in reset and wenb is HIGH, hold previous value on the next cycle.
    hold_on_wenb_high: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1) |=> (reg_0x1F == $past(reg_0x1F))
    );

// While reset remains asserted across cycles, the register is zero.
    reset_while_asserted_holds_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (reg_0x1F == 8'h00)
    );

// Even if in_data toggles, with wenb HIGH the register does not update.
    no_update_when_wenb_high_despite_data_change: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b1 && $changed(in_data)) |=> (reg_0x1F == $past(reg_0x1F))
    );

// On a write with data different from the current value, the register must change next cycle.
    write_with_different_data_changes_reg: assert property (
        @(posedge clk) disable iff (reset) (wenb == 1'b0 && (in_data != reg_0x1F)) |=> (reg_0x1F != $past(reg_0x1F))
    );

endmodule

rtl:
module parity_check (
  input [7:0] data,
  output reg parity_error
);
  wire [7:0] xor_result;

  assign xor_result = ^data;

  always @(*) begin
    parity_error <= (xor_result == 1);
  end
endmodule

sva:
module parity_check_sva (
    input logic CLK,
    input logic RESETn,
    input logic [7:0] data,
    input logic parity_error
);

// parity_error equals the reduction XOR of data (handles X/Z via case equality).
    check_parity_equals_reduction: assert property (
        @(posedge CLK) disable iff (!RESETn) (parity_error === (^data))
    );

// Fully known data implies parity_error is known (no X/Z).
    check_known_data_implies_known_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (!$isunknown(data)) |-> (!$isunknown(parity_error))
    );

// All-zero data has even parity -> parity_error is 0.
    check_zero_data_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'h00) |-> (parity_error == 1'b0)
    );

// All-ones (8'hFF) has even parity for 8 bits -> parity_error is 0.
    check_allones_even_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) (data == 8'hFF) |-> (parity_error == 1'b0)
    );

// Exactly one '1' in data (odd weight) -> parity_error is 1.
    check_onehot_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(data) |-> (parity_error == 1'b1)
    );

// Exactly one '0' in data (seven ones, odd) -> parity_error is 1.
    check_onecold_odd_parity: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot(~data) |-> (parity_error == 1'b1)
    );

endmodule

rtl:
module register_4bit (
    input [3:0] data_in,
    input load,
    input reset,
    input clk,
    output reg [3:0] Q
);

    // Local signals
    reg [3:0] Q_reg;

    // Instantiate 4 D Flip-Flops with Set and Reset functionality
    always @ (posedge clk or posedge reset)
    begin
        if (reset)
        begin
            Q_reg <= 4'b0;
        end
        else if (load)
        begin
            Q_reg <= data_in;
        end
    end

    always @*
    begin
        Q = Q_reg;
    end

endmodule

sva:
module register_4bit_sva (
    input logic [3:0] data_in,
    input logic load,
    input logic reset,   // active-high async reset in RTL
    input logic clk,
    input logic [3:0] Q
);

// After a sampled reset, Q must be 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) |-> (Q == 4'b0000)
    );

// With load high (reset low), Q updates to data_in on the next clock.
    check_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

// After a sampled reset, if no load in the following cycle, Q remains 0 for one more cycle.
    check_zero_persists_one_more_cycle_without_load_after_reset: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && !load |=> (Q == 4'b0000)
    );

// Back-to-back loads pipeline data: second cycle reflects data_in of the first next cycle.
    check_back_to_back_loads_pipeline: assert property (
        @(posedge clk) disable iff (reset) load ##1 load |=> (Q == $past(data_in))
    );

// If previous cycle had reset and current load is high, Q is 0 in the current cycle (reset dominates).
    check_reset_dominates_load_current: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |-> (Q == 4'b0000)
    );

// If previous cycle had reset and current load is high, Q captures current data on the next clock.
    check_reset_then_load_captures_next: assert property (
        @(posedge clk) disable iff (reset) $past(reset) && load |=> (Q == $past(data_in))
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input CI,
    output reg SUM,
    output reg COUT
);

    always @ (A or B or CI) begin
        SUM = A ^ B ^ CI;
        COUT = (A & B) | (B & CI) | (CI & A);
    end

endmodule

sva:
module full_adder_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic CI,
    input logic SUM,
    input logic COUT
);

// SUM must equal A xor B xor CI.
    check_sum_logic: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT must equal majority of A,B,CI (carry-out).
    check_cout_logic: assert property (
        @(posedge CLK) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// {COUT,SUM} equals the 2-bit addition of inputs.
    check_add_result_vector: assert property (
        @(posedge CLK) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CI})
    );

// 000 inputs produce 00 outputs.
    truth_000: assert property (
        @(posedge CLK) (A == 1'b0 && B == 1'b0 && CI == 1'b0) |-> (SUM == 1'b0 && COUT == 1'b0)
    );

// 111 inputs produce 11 outputs.
    truth_111: assert property (
        @(posedge CLK) (A == 1'b1 && B == 1'b1 && CI == 1'b1) |-> (SUM == 1'b1 && COUT == 1'b1)
    );

// Exactly one input high yields SUM=1 and COUT=0.
    onehot_sum_only: assert property (
        @(posedge CLK) $onehot({A,B,CI}) |-> (SUM == 1'b1 && COUT == 1'b0)
    );

// Exactly two inputs high yields SUM=0 and COUT=1.
    two_ones_cout_only: assert property (
        @(posedge CLK) ((A & B & ~CI) | (A & CI & ~B) | (B & CI & ~A)) |-> (SUM == 1'b0 && COUT == 1'b1)
    );

// SUM=1 and COUT=1 implies all three inputs are 1.
    sum_and_cout_imply_three_ones: assert property (
        @(posedge CLK) (SUM == 1'b1 && COUT == 1'b1) |-> (A & B & CI)
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic load,
    input logic [3:0] input_data,
    input logic [3:0] Q
);

// When load is HIGH, next Q equals current input_data.
    check_load_captures_input_data: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

// When load is LOW and up_down is HIGH, next Q increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == (($past(Q) + 1) & 4'hF))
    );

// When load is LOW and up_down is LOW, next Q decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == (($past(Q) - 1) & 4'hF))
    );

// Increment from 0xF wraps to 0x0 when not loading.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrement from 0x0 wraps to 0xF when not loading.
    check_wrap_decrement_from_min: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Two consecutive UP steps (no load) increment Q by 2 (mod 16).
    check_two_cycle_increment: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && up_down) |=> (Q == (($past(Q,2) + 2) & 4'hF))
    );

// Two consecutive DOWN steps (no load) decrement Q by 2 (mod 16).
    check_two_cycle_decrement: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && !up_down) |=> (Q == (($past(Q,2) - 2) & 4'hF))
    );

// UP followed by DOWN with no loads returns Q to original value after 2 cycles.
    check_up_then_down_cancels: assert property (
        @(posedge clk) (!load && up_down) ##1 (!load && !up_down) |=> (Q == $past(Q,2))
    );

// DOWN followed by UP with no loads returns Q to original value after 2 cycles.
    check_down_then_up_cancels: assert property (
        @(posedge clk) (!load && !up_down) ##1 (!load && up_down) |=> (Q == $past(Q,2))
    );

// Two consecutive loads use the second cycle's input_data value.
    check_two_consecutive_loads_use_second_value: assert property (
        @(posedge clk) load ##1 load |=> (Q == $past(input_data,1))
    );

endmodule

rtl:
module posManager (
   input         clk,
   input [15:0]  pos11,
   input [15:0]  pos12,
   input [15:0]  pos21,
   input [15:0]  pos22,
   output [15:0] pos_diff_x,
   output [15:0] pos_diff_y,
   output [31:0] count_clk,
   input  [1:0]  clear,
   input  [0:0]  m1,
   input  [0:0]  m2
);

   reg [15:0] prev_pos11, prev_pos12, prev_pos21, prev_pos22;
   reg [31:0] prev_count_clk;

   always @(posedge clk) begin
      if (clear == 2'b10 || clear == 2'b11) begin
         prev_count_clk <= 0;
      end else begin
         prev_count_clk <= prev_count_clk + 1;
      end

      if (clear == 2'b01 || clear == 2'b10 || clear == 2'b11) begin
         prev_pos11 <= pos11;
         prev_pos12 <= pos12;
         prev_pos21 <= pos21;
         prev_pos22 <= pos22;
      end else begin
         if (m1 == 1'b1) begin
            prev_pos11 <= prev_pos11 + 1;
            prev_pos12 <= prev_pos12 + 1;
         end else begin
            prev_pos11 <= prev_pos11 - 1;
            prev_pos12 <= prev_pos12 - 1;
         end

         if (m2 == 1'b1) begin
            prev_pos21 <= prev_pos21 + 1;
            prev_pos22 <= prev_pos22 + 1;
         end else begin
            prev_pos21 <= prev_pos21 - 1;
            prev_pos22 <= prev_pos22 - 1;
         end
      end
   end

   assign pos_diff_x = clear == 2'b10 || clear == 2'b11 ? 0 : pos11 - pos21;
   assign pos_diff_y = clear == 2'b10 || clear == 2'b11 ? 0 : pos12 - pos22;
   assign count_clk = clear == 2'b10 || clear == 2'b11 ? 0 : prev_count_clk;

endmodule

sva:
module posManager_sva (
   input logic        clk,
   input logic [15:0] pos11,
   input logic [15:0] pos12,
   input logic [15:0] pos21,
   input logic [15:0] pos22,
   input logic [15:0] pos_diff_x,
   input logic [15:0] pos_diff_y,
   input logic [31:0] count_clk,
   input logic [1:0]  clear,
   input logic [0:0]  m1,
   input logic [0:0]  m2
);

// Clock: clk (posedge). No explicit reset. Mixed logic: sequential counter, combinational diffs with clear gating.

   // count_clk must be 0 when clear is 2'b10 or 2'b11.
   check_count_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (count_clk == 32'd0)
   );

// pos_diff_x must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffx_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == 16'd0)
   );

// pos_diff_y must be 0 when clear is 2'b10 or 2'b11.
   check_posdiffy_zero_on_clear_hi: assert property (
      @(posedge clk) ((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == 16'd0)
   );

// pos_diff_x equals pos11 - pos21 when clear is not 2'b10 or 2'b11.
   check_posdiffx_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_x == (pos11 - pos21))
   );

// pos_diff_y equals pos12 - pos22 when clear is not 2'b10 or 2'b11.
   check_posdiffy_calc_when_active: assert property (
      @(posedge clk) !((clear == 2'b10) || (clear == 2'b11)) |-> (pos_diff_y == (pos12 - pos22))
   );

// With two consecutive active cycles, count_clk increments by 1 each cycle.
   check_count_inc_on_two_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk) + 32'd1)
   );

// With three consecutive active cycles, count_clk increases by 2 over two cycles.
   check_count_inc_by_two_on_three_active: assert property (
      @(posedge clk)
      ( !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) ##1 !((clear == 2'b10) || (clear == 2'b11)) )
      |-> (count_clk == $past(count_clk,2) + 32'd2)
   );

endmodule

rtl:
module vending_machine (
    input coin,
    input button1,
    input button2,
    input button3,
    output product1,
    output product2,
    output product3,
    output change
);

    wire valid_selection = (button1 | button2 | button3) & ~coin;

    assign product1 = (valid_selection & button1) ? 1'b1 : 1'b0;
    assign product2 = (valid_selection & button2) ? 1'b1 : 1'b0;
    assign product3 = (valid_selection & button3) ? 1'b1 : 1'b0;
    assign change = coin & ~valid_selection;

endmodule

sva:
module vending_machine_sva (
    input logic CLK,
    input logic coin,
    input logic button1,
    input logic button2,
    input logic button3,
    input logic product1,
    input logic product2,
    input logic product3,
    input logic change
);

// product1 equals button1 & ~coin
    check_product1_func_equiv: assert property (
        @(posedge CLK) product1 == (button1 & ~coin)
    );

// product2 equals button2 & ~coin
    check_product2_func_equiv: assert property (
        @(posedge CLK) product2 == (button2 & ~coin)
    );

// product3 equals button3 & ~coin
    check_product3_func_equiv: assert property (
        @(posedge CLK) product3 == (button3 & ~coin)
    );

// change equals coin
    check_change_equals_coin: assert property (
        @(posedge CLK) change == coin
    );

// If coin is HIGH, all product outputs must be LOW
    check_coin_high_blocks_products: assert property (
        @(posedge CLK) coin |-> !(product1 | product2 | product3)
    );

// If any button is pressed with coin LOW, at least one product is HIGH
    check_any_button_no_coin_causes_some_product: assert property (
        @(posedge CLK) (~coin & (button1 | button2 | button3)) |-> (product1 | product2 | product3)
    );

// product1 HIGH implies button1 is HIGH
    check_product1_implies_button1: assert property (
        @(posedge CLK) product1 |-> button1
    );

// product2 HIGH implies button2 is HIGH
    check_product2_implies_button2: assert property (
        @(posedge CLK) product2 |-> button2
    );

// product3 HIGH implies button3 is HIGH
    check_product3_implies_button3: assert property (
        @(posedge CLK) product3 |-> button3
    );

// Products and change are mutually exclusive
    check_change_and_products_mutex: assert property (
        @(posedge CLK) (product1 | product2 | product3) |-> !change
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic EN,
    input logic RST,
    input logic [3:0] COUNT
);

///// Reset behavior /////
    // When reset is asserted (active-low), COUNT is 0 in the same cycle.
    reset_level_forces_zero: assert property (
        @(posedge clk) (RST == 1'b0) |-> (COUNT == 4'b0000)
    );

// If reset was asserted in the previous cycle, COUNT is 0 now.
    reset_previous_cycle_low_forces_zero: assert property (
        @(posedge clk) ($past(RST) == 1'b0) |-> (COUNT == 4'b0000)
    );

// On a sampled falling edge of reset, COUNT is 0.
    reset_fall_sampled_forces_zero: assert property (
        @(posedge clk) $fell(RST) |-> (COUNT == 4'b0000)
    );

// On a sampled rising edge of reset (previous cycle in reset), COUNT is 0.
    reset_rise_sampled_shows_zero: assert property (
        @(posedge clk) $rose(RST) |-> (COUNT == 4'b0000)
    );

// Reset has priority over enable; if both active, COUNT is 0.
    reset_priority_over_enable: assert property (
        @(posedge clk) (RST == 1'b0 && EN == 1'b1) |-> (COUNT == 4'b0000)
    );

// COUNT must be known while reset is asserted.
    no_x_during_reset: assert property (
        @(posedge clk) (RST == 1'b0) |-> (!$isunknown(COUNT))
    );

endmodule

