module mux_4to1_en (input [3:0] in0, in1, in2, in3,
                     input [1:0] sel,
                     input en,
                     output reg [3:0] out);

    always @(*) begin
        case (sel)
            2'b00: out = en ? in0 : 4'b0000;
            2'b01: out = en ? in1 : 4'b0000;
            2'b10: out = en ? in2 : 4'b0000;
            2'b11: out = en ? in3 : 4'b0000;
        endcase
    end

endmodule

sva:
module mux_4to1_en_sva (
    input logic clk,               // verification clock (RTL has no clock/reset)
    input logic [3:0] in0, in1, in2, in3,
    input logic [1:0] sel,
    input logic en,
    input logic [3:0] out
);

// Analysis: No clock/reset in RTL; purely combinational always @(*); out = en ? selected in : 4'b0000.

    // en low forces out to zero.
    check_out_zero_when_disabled: assert property (
        @(posedge clk) disable iff (1'b0) (!en) |-> (out == 4'b0000)
    );

// When en=1 and sel==00, out equals in0.
    check_sel_00_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b00)) |-> (out == in0)
    );

// When en=1 and sel==01, out equals in1.
    check_sel_01_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b01)) |-> (out == in1)
    );

// When en=1 and sel==10, out equals in2.
    check_sel_10_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b10)) |-> (out == in2)
    );

// When en=1 and sel==11, out equals in3.
    check_sel_11_route: assert property (
        @(posedge clk) disable iff (1'b0) (en && (sel == 2'b11)) |-> (out == in3)
    );

// Functional equivalence to the mux with enable.
    check_functional_equivalence: assert property (
        @(posedge clk) disable iff (1'b0)
            out == (en ? (sel == 2'b00 ? in0 :
                          sel == 2'b01 ? in1 :
                          sel == 2'b10 ? in2 : in3)
                      : 4'b0000)
    );

endmodule

rtl:
module counter_mod_rtl(
  input clk, rst, up_down,
  output reg [3:0] q,
  output reg carry
);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      q <= 4'b0;
      carry <= 1'b0;
    end else if (up_down == 1'b0) begin
      // Up counter
      if (q == 4'b1111) begin
        q <= 4'b0;
        carry <= 1'b1;
      end else begin
        q <= q + 4'b1;
        carry <= 1'b0;
      end
    end else begin
      // Down counter
      if (q == 4'b0000) begin
        q <= 4'b1111;
        carry <= 1'b1;
      end else begin
        q <= q - 4'b1;
        carry <= 1'b0;
      end
    end
  end

endmodule

sva:
module counter_mod_rtl_sva (
  input logic clk,
  input logic rst,
  input logic up_down,
  input logic [3:0] q,
  input logic carry
);

// Reset drives q and carry LOW when rst is HIGH at the clock edge.
  check_reset_outputs: assert property (
    @(posedge clk) rst |-> (q == 4'b0000) && (carry == 1'b0)
  );

// No spurious carry when last q was mid-range (1..14).
  check_no_carry_midrange: assert property (
    @(posedge clk) disable iff (rst)
      (!$past(rst) && ($past(q) != 4'd0) && ($past(q) != 4'hF))
      |-> (carry == 1'b0)
  );

endmodule

