        @(posedge clk) disable iff (clr) (y == 1'b0) |-> ((d0 == 1'b0) && (d1 == 1'b0))
    );

// If output is 1, at least one input must be 1.
    check_one_implies_any_one: assert property (
        @(posedge clk) disable iff (clr) (y == 1'b1) |-> ((d0 == 1'b1) || (d1 == 1'b1))
    );

// When d1 is 0, output equals d0.
    check_equals_d0_when_d1_zero: assert property (
        @(posedge clk) disable iff (clr) (d1 == 1'b0) |-> (y == d0)
    );

// When d0 is 0, output equals d1.
    check_equals_d1_when_d0_zero: assert property (
        @(posedge clk) disable iff (clr) (d0 == 1'b0) |-> (y == d1)
    );

// If inputs are known (not X/Z), output is known (not X/Z).
    check_no_unknown_output_when_inputs_known: assert property (
        @(posedge clk) disable iff (clr) (!$isunknown(d0) && !$isunknown(d1)) |-> !$isunknown(y)
    );

endmodule

rtl:
module MUX4_1_SL(Sel, S0, S1, S2, S3, out);

input [1:0] Sel;
input [3:0] S0, S1, S2, S3;
output [3:0] out;

assign out = (Sel[1] ? (Sel[0] ? S3 : S2) : (Sel[0] ? S1 : S0));

endmodule

sva:
module MUX4_1_SL_sva (
    input logic CLK,
    input logic [1:0] Sel,
    input logic [3:0] S0,
    input logic [3:0] S1,
    input logic [3:0] S2,
    input logic [3:0] S3,
    input logic [3:0] out
);

// Out equals S0 when Sel is 2'b00.
    check_sel00_routes_S0: assert property (
        @(posedge CLK) (Sel == 2'b00) |-> (out == S0)
    );

// Out equals S1 when Sel is 2'b01.
    check_sel01_routes_S1: assert property (
        @(posedge CLK) (Sel == 2'b01) |-> (out == S1)
    );

// Out equals S2 when Sel is 2'b10.
    check_sel10_routes_S2: assert property (
        @(posedge CLK) (Sel == 2'b10) |-> (out == S2)
    );

// Out equals S3 when Sel is 2'b11.
    check_sel11_routes_S3: assert property (
        @(posedge CLK) (Sel == 2'b11) |-> (out == S3)
    );

// Structural equivalence to the RTL ternary expression.
    check_functional_equivalence: assert property (
        @(posedge CLK) out == (Sel[1] ? (Sel[0] ? S3 : S2) : (Sel[0] ? S1 : S0))
    );

// When Sel[1]==0, out selects between S1 and S0 per Sel[0].
    check_lower_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b0) |-> (out == (Sel[0] ? S1 : S0))
    );

// When Sel[1]==1, out selects between S3 and S2 per Sel[0].
    check_upper_half_select: assert property (
        @(posedge CLK) (Sel[1] == 1'b1) |-> (out == (Sel[0] ? S3 : S2))
    );

endmodule

rtl:
module counter (
   // Inputs
   input clk,
   input reset,
   input enable,
   // Outputs
   output reg [3:0] count,
   output reg overflow
   );

   always @(posedge clk) begin
      if (reset) begin
         count <= 4'b0000;
         overflow <= 1'b0;
      end else if (enable) begin
         if (count == 4'b1111) begin
            count <= 4'b0000;
            overflow <= 1'b1;
         end else begin
            count <= count + 1;
            overflow <= 1'b0;
         end
      end
   end

endmodule

sva:
module counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] count,
    input logic overflow
);

// Clock: posedge clk; Reset: active-high synchronous 'reset'; Logic: sequential.

    // Synchronous reset drives count=0 and overflow=0 on the following cycle.
    reset_clears_outputs_next: assert property (
        @(posedge clk) reset |=> (count == 4'h0) && (overflow == 1'b0)
    );

// When disabled, both outputs hold their previous values.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) (!enable) |=> (count == $past(count)) && (overflow == $past(overflow))
    );

// With enable and count==15, next count wraps to 0 and overflow asserts.
    wrap_sets_overflow_and_zero: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0) && (overflow == 1'b1)
    );

// With enable and count!=15, next count increments by 1.
    increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (count == $past(count) + 4'd1)
    );

// With enable and count!=15, next overflow is 0.
    no_overflow_on_non_wrap: assert property (
        @(posedge clk) disable iff (reset) (enable && (count != 4'hF)) |=> (overflow == 1'b0)
    );

// When enabled, count must change on the next cycle.
    count_changes_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count != $past(count))
    );

endmodule

rtl:
module johnson_counter_and (
    input clk,
    input reset,
    input [7:0] input_val,
    output [63:0] output_val
);

reg [63:0] counter;

always @(posedge clk) begin
    if (reset) begin
        counter <= 64'b0000_0000_0000_0000_0000_0000_0000_0000;
    end else begin
        counter <= {counter[62:0], counter[63] ^ counter[0]};
    end
end

assign output_val = counter & {64{input_val}};

endmodule

sva:
module johnson_counter_and_sva (
    input logic clk,
    input logic reset,
    input logic [7:0] input_val,
    input logic [63:0] output_val,
    input logic [63:0] counter
);

// On reset, counter must be all zeros on the next cycle.
    check_reset_clears_counter_next: assert property (
        @(posedge clk) reset |=> (counter == 64'b0)
    );

// On reset, output must be all zeros on the next cycle.
    check_reset_clears_output_next: assert property (
        @(posedge clk) reset |=> (output_val == 64'b0)
    );

// Output bits can only be 1 where the replicated input mask bits are 1.
    check_output_mask_subset: assert property (
        @(posedge clk) disable iff (reset)
            (output_val & ~{8{input_val}}) == 64'b0
    );

// If the input mask is all zeros, the output must be zero.
    check_output_zero_when_input_zero: assert property (
        @(posedge clk) disable iff (reset)
            (input_val == 8'h00) |-> (output_val == 64'b0)
    );

endmodule

module my_buffer_sva (
    input logic A,
    input logic Z,
    input logic TE_B,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

///// Functional equivalence /////
    // Z must equal TE_B & A when sampled on A rising.
    check_func_equiv_on_A: assert property (
        @(posedge A) Z == (TE_B & A)
    );

// Z must equal TE_B & A when sampled on TE_B rising.
    check_func_equiv_on_TEB: assert property (
        @(posedge TE_B) Z == (TE_B & A)
    );

///// Enable low forces zero /////
    // If TE_B is LOW, Z must be 0 (sampled on A rising).
    check_zero_when_teb_low_on_A: assert property (
        @(posedge A) (TE_B == 1'b0) |-> (Z == 1'b0)
    );

///// Enable high passes A /////
    // If TE_B is HIGH, Z equals A (sampled on A rising).
    check_passthrough_when_teb_high_on_A: assert property (
        @(posedge A) (TE_B == 1'b1) |-> (Z == A)
    );

///// Output implications /////
    // If Z is HIGH, both TE_B and A must be HIGH (sampled on A rising).
    check_z_high_implies_inputs_high_on_A: assert property (
        @(posedge A) (Z == 1'b1) |-> (TE_B == 1'b1 && A == 1'b1)
    );

endmodule

rtl:
module digital_circuit (
    input  D   ,
    output Q   ,
    output Q_N ,
    input  SCD ,
    input  SCE ,
    input  CLK ,
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);

wire D_ff;
reg Q_ff;
wire Q_N_ff;

assign D_ff = SCE ? SCD : D;

always @(posedge CLK) begin
    Q_ff <= D_ff;
end

assign Q = Q_ff;
assign Q_N = ~Q_ff;

endmodule

sva:
module digital_circuit_sva (
    input logic D,
    input logic Q,
    input logic Q_N,
    input logic SCD,
    input logic SCE,
    input logic CLK,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

///// Output relationships /////
    // Q_N is always the bitwise inverse of Q.
    check_qn_is_invert_of_q: assert property (
        @(posedge CLK) (Q_N === ~Q)
    );

///// Capture behavior /////
    // Q captures the selected input (SCE ? SCD : D) from the previous cycle.
    check_q_captures_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q == $past(SCE ? SCD : D))
    );

// Q_N captures the inverse of the selected input from the previous cycle.
    check_qn_captures_inverted_mux_prev: assert property (
        @(posedge CLK) 1'b1 ##1 (Q_N === ~$past(SCE ? SCD : D))
    );

///// Scan enable selection /////
    // When SCE=0, Q captures D on the next rising edge.
    check_q_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q == $past(D))
    );

// When SCE=1, Q captures SCD on the next rising edge.
    check_q_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q == $past(SCD))
    );

// When SCE=0, Q_N captures ~D on the next rising edge.
    check_qn_from_d_when_sce0: assert property (
        @(posedge CLK) (SCE == 1'b0) |=> (Q_N === ~$past(D))
    );

// When SCE=1, Q_N captures ~SCD on the next rising edge.
    check_qn_from_scd_when_sce1: assert property (
        @(posedge CLK) (SCE == 1'b1) |=> (Q_N === ~$past(SCD))
    );

endmodule

rtl:
module sky130_fd_sc_hdll__nand4bb (
    Y  ,
    A_N,
    B_N,
    C  ,
    D
);

    output Y  ;
    input  A_N;
    input  B_N;
    input  C  ;
    input  D  ;

    wire nand0_out;
    wire or0_out_Y;

    nand nand0 (nand0_out, D, C               );
    or   or0   (or0_out_Y, B_N, A_N, nand0_out);
    buf  buf0  (Y        , or0_out_Y          );

endmodule

sva:
module sky130_fd_sc_hdll__nand4bb_sva (
    input  logic clk,
    input  logic Y,
    input  logic A_N,
    input  logic B_N,
    input  logic C,
    input  logic D
);

// Y equals A_N | B_N | ~C | ~D.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (A_N | B_N | (~C) | (~D))
    );

// Y is 0 only when A_N=0, B_N=0, C=1, and D=1.
    check_y_zero_only_in_one_case: assert property (
        @(posedge clk) (Y == 1'b0) |-> ((A_N == 1'b0) && (B_N == 1'b0) && (C == 1'b1) && (D == 1'b1))
    );

// When C=1 and D=1, Y reduces to A_N | B_N.
    check_reduce_when_c_and_d_high: assert property (
        @(posedge clk) (C && D) |-> (Y == (A_N | B_N))
    );

// When A_N=0 and B_N=0, Y reduces to ~C | ~D.
    check_reduce_when_a_and_b_low: assert property (
        @(posedge clk) (!A_N && !B_N) |-> (Y == ((~C) | (~D)))
    );

// A_N=1 forces Y=1.
    check_a_n_high_forces_y_high: assert property (
        @(posedge clk) A_N |-> (Y == 1'b1)
    );

// B_N=1 forces Y=1.
    check_b_n_high_forces_y_high: assert property (
        @(posedge clk) B_N |-> (Y == 1'b1)
    );

// C=0 forces Y=1.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) (!C) |-> (Y == 1'b1)
    );

// D=0 forces Y=1.
    check_d_low_forces_y_high: assert property (
        @(posedge clk) (!D) |-> (Y == 1'b1)
    );

// If Y=0 then A_N must be 0.
    check_y_zero_implies_a_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A_N == 1'b0)
    );

// If Y=0 then B_N must be 0.
    check_y_zero_implies_b_n_low: assert property (
        @(posedge clk) (Y == 1'b0) |-> (B_N == 1'b0)
    );

// If Y=0 then C must be 1.
    check_y_zero_implies_c_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (C == 1'b1)
    );

// If Y=0 then D must be 1.
    check_y_zero_implies_d_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (D == 1'b1)
    );

endmodule

