module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    input Clock,
    output [3:0] Sum,
    output Cout
);

reg [3:0] Sum;
reg Cout;

always @(posedge Clock) begin
    {Cout, Sum} = A + B + Cin;
end

endmodule

sva:
module four_bit_adder_assertions (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic Clock,
    input logic [3:0] Sum,
    input logic Cout
);

// Sum registers the previous cycle's 4-bit addition of A, B, and Cin.
    check_sum_matches_previous_add: assert property (
        @(posedge Clock) 1'b1 |=> (Sum == ($past(A) + $past(B) + $past(Cin)))
    );

endmodule

rtl:
module sky130_fd_sc_hvl__a21oi (
    Y ,
    A1,
    A2,
    B1
);

    output Y ;
    input  A1;
    input  A2;
    input  B1;

    wire and0_out  ;
    wire nor0_out_Y;

    and and0 (and0_out  , A1, A2         );
    nor nor0 (nor0_out_Y, B1, and0_out   );
    buf buf0 (Y         , nor0_out_Y     );

endmodule

sva:
module sky130_fd_sc_hvl__a21oi_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1
);

// DUT is combinational; clk is an external sampling clock and there is no reset.

    // Y matches the implemented AOI21 boolean function.
    check_boolean_function: assert property (
        @(posedge clk) Y == ~(B1 | (A1 & A2))
    );

// A high B1 input forces Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> ~Y
    );

// High A1 and A2 force the AND term high and drive Y low.
    check_and_term_forces_y_low: assert property (
        @(posedge clk) (A1 & A2) |-> ~Y
    );

// When B1 is low, Y reduces to the inverse of A1&A2.
    check_b1_low_reduces_to_nand: assert property (
        @(posedge clk) (~B1) |-> (Y == ~(A1 & A2))
    );

// A high output requires B1 to be low.
    check_y_high_requires_b1_low: assert property (
        @(posedge clk) Y |-> ~B1
    );

// A high output requires the A1/A2 AND term to be low.
    check_y_high_requires_and_term_low: assert property (
        @(posedge clk) Y |-> (~A1 | ~A2)
    );

// A low output must be caused by B1 or the A1/A2 AND term being high.
    check_y_low_has_valid_cause: assert property (
        @(posedge clk) (~Y) |-> (B1 | (A1 & A2))
    );

endmodule

rtl:
module top_module ( 
    input wire clk,
    input wire [2:0] sel, 
    input wire [3:0] data0,
    input wire [3:0] data1,
    input wire [3:0] data2,
    input wire [3:0] data3,
    input wire [3:0] data4,
    input wire [3:0] data5,
    output wire [3:0] out_mux,
    output wire [2:0] out_3bit,
    output wire o2,
    output wire o1,
    output wire o0,
    output wire [6:0] final_out
);

// 6-to-1 Multiplexer
wire [3:0] mux_out;
assign mux_out = (sel == 0) ? data0 :
                 (sel == 1) ? data1 :
                 (sel == 2) ? data2 :
                 (sel == 3) ? data3 :
                 (sel == 4) ? data4 :
                 (sel == 5) ? data5 : 4'b0;
assign out_mux = mux_out;

// 3-bit Input Module
assign out_3bit = sel;
assign o2 = sel[2];
assign o1 = sel[1];
assign o0 = sel[0];

// Functional Module
wire [6:0] add_out;
wire carry_out;
assign {carry_out, add_out} = {1'b0, mux_out} + {1'b0, sel};
assign final_out = {carry_out, add_out};

endmodule

sva:
module top_module_assertions (
    input logic        clk,
    input logic [2:0]  sel,
    input logic [3:0]  data0,
    input logic [3:0]  data1,
    input logic [3:0]  data2,
    input logic [3:0]  data3,
    input logic [3:0]  data4,
    input logic [3:0]  data5,
    input logic [3:0]  out_mux,
    input logic [2:0]  out_3bit,
    input logic        o2,
    input logic        o1,
    input logic        o0,
    input logic [6:0]  final_out
);

// out_mux selects data0 when sel is 0.
    check_out_mux_sel0: assert property (
        @(posedge clk) (sel == 3'd0) |-> (out_mux == data0)
    );

// out_mux selects data1 when sel is 1.
    check_out_mux_sel1: assert property (
        @(posedge clk) (sel == 3'd1) |-> (out_mux == data1)
    );

// out_mux selects data2 when sel is 2.
    check_out_mux_sel2: assert property (
        @(posedge clk) (sel == 3'd2) |-> (out_mux == data2)
    );

// out_mux selects data3 when sel is 3.
    check_out_mux_sel3: assert property (
        @(posedge clk) (sel == 3'd3) |-> (out_mux == data3)
    );

// out_mux selects data4 when sel is 4.
    check_out_mux_sel4: assert property (
        @(posedge clk) (sel == 3'd4) |-> (out_mux == data4)
    );

// out_mux selects data5 when sel is 5.
    check_out_mux_sel5: assert property (
        @(posedge clk) (sel == 3'd5) |-> (out_mux == data5)
    );

// out_mux is zero when sel is outside 0 through 5.
    check_out_mux_default_zero: assert property (
        @(posedge clk) ((sel == 3'd6) || (sel == 3'd7)) |-> (out_mux == 4'b0000)
    );

// out_3bit mirrors sel.
    check_out_3bit_matches_sel: assert property (
        @(posedge clk) out_3bit == sel
    );

// o2 mirrors sel[2].
    check_o2_matches_sel_bit2: assert property (
        @(posedge clk) o2 == sel[2]
    );

// o1 mirrors sel[1].
    check_o1_matches_sel_bit1: assert property (
        @(posedge clk) o1 == sel[1]
    );

// o0 mirrors sel[0].
    check_o0_matches_sel_bit0: assert property (
        @(posedge clk) o0 == sel[0]
    );

// final_out is the zero-extended sum of the selected mux input and sel.
    check_final_out_sum: assert property (
        @(posedge clk)
        final_out ==
        ({3'b000, ((sel == 3'd0) ? data0 :
                   (sel == 3'd1) ? data1 :
                   (sel == 3'd2) ? data2 :
                   (sel == 3'd3) ? data3 :
                   (sel == 3'd4) ? data4 :
                   (sel == 3'd5) ? data5 : 4'b0000)} + {4'b0000, sel})
    );

endmodule

