module and_with_en (
    in1,
    in2,
    en,
    out,
    out_valid
);

    input in1;
    input in2;
    input en;
    output out;
    output out_valid;

    wire and_out;

    and and_gate(and_out, in1, in2);

    assign out = and_out & en;
    assign out_valid = en;

endmodule

sva:
module and_with_en_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic en,
    input logic out,
    input logic out_valid
);

// No DUT clock/reset; this checker samples the combinational interface on clk.

    // out_valid is exactly the enable signal.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// out is the AND of both inputs gated by enable.
    check_out_matches_function: assert property (
        @(posedge clk) out == (in1 & in2 & en)
    );

// When enable is low, out must be low.
    check_disable_forces_out_low: assert property (
        @(posedge clk) !en |-> !out
    );

// A high out requires both inputs high and enable asserted.
    check_out_high_requires_all_inputs: assert property (
        @(posedge clk) out |-> (in1 && in2 && en && out_valid)
    );

// When enabled and both inputs are high, out must be high.
    check_enabled_high_inputs_drive_out: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

endmodule

rtl:
module MUXCY (O, CO, CI, DI, S, CIN);

    output O;
    output CO;
    input CI, DI, S, CIN;

    wire A, B, C, D;

    assign A = S & DI;
    assign B = ~S & CI;
    assign O = A | B;

    assign C = CI & S;
    assign D = DI & (CI | S);
    assign CO = C | D;

endmodule

sva:
module MUXCY_sva (
    input logic clk,
    input logic O,
    input logic CO,
    input logic CI,
    input logic DI,
    input logic S,
    input logic CIN
);

// O matches the RTL mux equation.
    check_o_equation: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// CO matches the RTL carry equation.
    check_co_equation: assert property (
        @(posedge clk) CO == ((CI & S) | (DI & (CI | S)))
    );

// When S is high, O selects DI.
    check_o_selects_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

// When S is low, O selects CI.
    check_o_selects_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

// When S is high, CO reduces to CI OR DI.
    check_co_reduces_to_or_when_s_high: assert property (
        @(posedge clk) S |-> (CO == (CI | DI))
    );

// When S is low, CO reduces to CI AND DI.
    check_co_reduces_to_and_when_s_low: assert property (
        @(posedge clk) !S |-> (CO == (CI & DI))
    );

// Equal data inputs force both outputs to that shared value.
    check_equal_inputs_drive_equal_outputs: assert property (
        @(posedge clk) (CI == DI) |-> ((O == CI) && (CO == CI))
    );

endmodule

rtl:
module ClockGating (
  input CLK, EN, TE, RESET,
  output reg ENCLK
);

always @ (posedge CLK, posedge RESET) begin
  if (RESET) begin
    ENCLK <= 0;
  end else if (EN) begin
    if (TE) begin
      ENCLK <= 0;
    end else begin
      ENCLK <= ~CLK;
    end
  end else begin
    ENCLK <= 0;
  end
end

endmodule

sva:
module ClockGating_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic RESET,
    input logic ENCLK
);

// Any reset cycle leaves ENCLK low by the next observed clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |=> (ENCLK == 1'b0)
    );

// With EN low, the RTL takes the else branch and drives ENCLK low.
    check_en_low_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (!EN) |=> (ENCLK == 1'b0)
    );

// With EN and TE high, the TE branch drives ENCLK low.
    check_te_high_drives_enclk_low: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

endmodule

rtl:
module addsub(
    input [3:0] A,
    input [3:0] B,
    input SUB,
    output [3:0] OUT,
    output COUT
);

wire [3:0] B_INV;
wire [3:0] ADD;
wire SUB_NEG;

// Invert B
assign B_INV = ~B;

// Add 1 to inverted B to perform subtraction
assign ADD = SUB ? A + B_INV : A + B;

// Determine if output is negative
assign SUB_NEG = ADD[3];

// Set COUT based on sign bit
assign COUT = SUB_NEG;

// Output result
assign OUT = SUB ? B_INV + 1 : ADD;

endmodule

sva:
module addsub_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] OUT,
    input logic COUT,
    input logic [3:0] B_INV,
    input logic [3:0] ADD,
    input logic SUB_NEG
);

// OUT matches A+B in add mode.
    check_out_matches_sum_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (OUT == (A + B))
    );

// COUT matches OUT[3] in add mode.
    check_cout_matches_out_msb_in_add_mode: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (COUT == OUT[3])
    );

// OUT matches ~B+1 in subtract mode.
    check_out_matches_twos_complement_b_in_sub_mode: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (OUT == ((~B) + 4'd1))
    );

endmodule

rtl:
module binary_decoder_3to8 (
    input [2:0] in,      // 3-bit input
    output reg [7:0] out // 8-bit output
);

    always @(*) begin
        // Initialize output to 0
        out = 8'b00000000;

        // Decode the input to one-hot output
        case (in)
            3'b000: out[0] = 1'b1;
            3'b001: out[1] = 1'b1;
            3'b010: out[2] = 1'b1;
            3'b011: out[3] = 1'b1;
            3'b100: out[4] = 1'b1;
            3'b101: out[5] = 1'b1;
            3'b110: out[6] = 1'b1;
            3'b111: out[7] = 1'b1;
            default: out = 8'b00000000; // Default case to handle unknown states
        endcase
    end

endmodule

sva:
module binary_decoder_3to8_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] out
);

// Output is never multi-hot.
    check_out_onehot0: assert property (
        @(posedge clk) disable iff (1'b0) $onehot0(out)
    );

// Input 000 selects bit 0.
    check_decode_000: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b000) |-> (out == 8'b00000001)
    );

// Input 001 selects bit 1.
    check_decode_001: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b001) |-> (out == 8'b00000010)
    );

// Input 010 selects bit 2.
    check_decode_010: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b010) |-> (out == 8'b00000100)
    );

// Input 011 selects bit 3.
    check_decode_011: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b011) |-> (out == 8'b00001000)
    );

// Input 100 selects bit 4.
    check_decode_100: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b100) |-> (out == 8'b00010000)
    );

// Input 101 selects bit 5.
    check_decode_101: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b101) |-> (out == 8'b00100000)
    );

// Input 110 selects bit 6.
    check_decode_110: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b110) |-> (out == 8'b01000000)
    );

// Input 111 selects bit 7.
    check_decode_111: assert property (
        @(posedge clk) disable iff (1'b0) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Unknown input values drive the default zero output.
    check_decode_unknown_default_zero: assert property (
        @(posedge clk) disable iff (1'b0) $isunknown(in) |-> (out == 8'b00000000)
    );

endmodule

rtl:
module multi_input_module (
    X ,
    A1,
    A2,
    A3,
    A4,
    B1
);

    output X ;
    input  A1;
    input  A2;
    input  A3;
    input  A4;
    input  B1;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign X = ((A1&A2&A3) | (A1&A2&A4) | (A1&A3&A4) | (A2&A3&A4) | (A1&A2&B1) | (A1&A3&B1) | (A1&A4&B1) | (A2&A3&B1) | (A2&A4&B1) | (A3&A4&B1));

