module fourBitAdder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] temp_sum;

    assign temp_sum = A + B + Cin;
    assign Sum = temp_sum[3:0];
    assign Cout = temp_sum[4];

endmodule

sva:
module fourBitAdder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);

// Combined output must equal the 5-bit sum of A, B, and Cin.
    check_combined_result: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The least-significant sum bit must match A[0] xor B[0] xor Cin.
    check_lsb_xor_behavior: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With both operands zero, the output must only reflect Cin.
    check_zero_operands_cin_only: assert property (
        @(posedge clk) (A == 4'h0 && B == 4'h0) |-> ({Cout, Sum} == {4'b0000, Cin})
    );

// With A zero and Cin low, the output must pass B through with no carry.
    check_a_zero_b_passthrough: assert property (
        @(posedge clk) (A == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, B})
    );

// With B zero and Cin low, the output must pass A through with no carry.
    check_b_zero_a_passthrough: assert property (
        @(posedge clk) (B == 4'h0 && Cin == 1'b0) |-> ({Cout, Sum} == {1'b0, A})
    );

// Carry-out must be low when the computed sum fits in 4 bits.
    check_no_overflow_no_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) <= 5'd15) |-> (Cout == 1'b0)
    );

// Carry-out must be high when the computed sum exceeds 4 bits.
    check_overflow_sets_carry: assert property (
        @(posedge clk) (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16) |-> (Cout == 1'b1)
    );

// The maximum input combination must produce the maximum 5-bit result.
    check_maximum_input_sum: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> ({Cout, Sum} == 5'h1F)
    );

endmodule

rtl:
module top_module (
    input [3:0] binary_input, // 4-bit binary input
    input [1:0] shift_amount, // 2-bit shift amount input
    output [3:0] shifted_gray_code_output // 4-bit shifted Gray code output
);

wire [3:0] gray_code_output;

gray_code gray_code_inst (
    .in(binary_input),
    .out(gray_code_output)
);

barrel_shifter barrel_shifter_inst (
    .data(gray_code_output),
    .shift_amount(shift_amount),
    .result(shifted_gray_code_output)
);

endmodule

module gray_code (
    input [3:0] in,
    output [3:0] out
);

assign out[3] = in[3];
assign out[2] = in[3] ^ in[2];
assign out[1] = in[2] ^ in[1];
assign out[0] = in[1] ^ in[0];

endmodule

module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output [3:0] result
);

assign result = (shift_amount == 2'b00) ? data :
               (shift_amount == 2'b01) ? {data[2:0], data[3]} :
               (shift_amount == 2'b10) ? {data[1:0], data[3:2]} :
               {data[0], data[3:1]};

endmodule

sva:
module top_module_assertions (
    input logic clk,
    input logic [3:0] binary_input,
    input logic [1:0] shift_amount,
    input logic [3:0] shifted_gray_code_output
);

// No shift selects the direct Gray-code encoding.
    check_no_shift_gray_mapping: assert property (
        @(posedge clk)
        (shift_amount == 2'b00) |-> (
            shifted_gray_code_output ==
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])}
        )
    );

// Shift amount 1 rotates the Gray code left by 1 bit.
    check_shift_by_1_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b01) |-> (
            shifted_gray_code_output ==
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]}
        )
    );

// Shift amount 2 rotates the Gray code left by 2 bits.
    check_shift_by_2_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b10) |-> (
            shifted_gray_code_output ==
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])}
        )
    );

// Shift amount 3 rotates the Gray code left by 3 bits.
    check_shift_by_3_gray_rotation: assert property (
        @(posedge clk)
        (shift_amount == 2'b11) |-> (
            shifted_gray_code_output ==
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])}
        )
    );

// The top-level output always matches the composed Gray encoder and shifter.
    check_end_to_end_function: assert property (
        @(posedge clk)
        shifted_gray_code_output ==
        ((shift_amount == 2'b00) ?
            {binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0])} :
         (shift_amount == 2'b01) ?
            {(binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3]} :
         (shift_amount == 2'b10) ?
            {(binary_input[2] ^ binary_input[1]),
             (binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2])} :
            {(binary_input[1] ^ binary_input[0]),
             binary_input[3],
             (binary_input[3] ^ binary_input[2]),
             (binary_input[2] ^ binary_input[1])})
    );

endmodule

