rtl:
module mux4(
    input A0,
    input A1,
    input A2,
    input A3,
    input S0,
    input S1,
    output reg X
);

wire SA, SB, SC, SD, SE, SF, SG, SH;

assign SA = A0 & ~S0 & ~S1;
assign SB = A1 & S0 & ~S1;
assign SC = A2 & ~S0 & S1;
assign SD = A3 & S0 & S1;

assign SE = SA | SB;
assign SF = SC | SD;

assign SG = SE & ~S1;
assign SH = SF & S1;

// Use a blocking assignment to set the value of X
always @* begin
    X = SG | SH;
end

endmodule

sva:
module mux4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic X
);

// X must match the full mux sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        X == ((A0 & ~S0 & ~S1) |
              (A1 &  S0 & ~S1) |
              (A2 & ~S0 &  S1) |
              (A3 &  S0 &  S1))
    );

// When select is 00, X must follow A0.
    check_select_00: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b0)) |-> (X == A0)
    );

// When select is 01, X must follow A1.
    check_select_01: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b0) && (S0 == 1'b1)) |-> (X == A1)
    );

// When select is 10, X must follow A2.
    check_select_10: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b0)) |-> (X == A2)
    );

// When select is 11, X must follow A3.
    check_select_11: assert property (
        @(posedge clk) disable iff (1'b0)
        ((S1 == 1'b1) && (S0 == 1'b1)) |-> (X == A3)
    );

// With S1 low, X must select between A0 and A1 using S0.
    check_s1_low_lower_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0) |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

// With S1 high, X must select between A2 and A3 using S0.
    check_s1_high_upper_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1) |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

// With S0 low, X must select between A0 and A2 using S1.
    check_s0_low_even_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b0) |-> (X == ((A0 & ~S1) | (A2 & S1)))
    );

// With S0 high, X must select between A1 and A3 using S1.
    check_s0_high_odd_pair: assert property (
        @(posedge clk) disable iff (1'b0)
        (S0 == 1'b1) |-> (X == ((A1 & ~S1) | (A3 & S1)))
    );

endmodule

rtl:
module dff_en(input D, C, E, output Q);
  reg Q;

  always @(posedge C) begin
    if (E) begin
      Q <= D;
    end
  end

endmodule

sva:
module dff_en_assertions (
    input logic D,
    input logic C,
    input logic E,
    input logic Q
);

// An enabled rising edge loads D into Q.
    check_load_on_enable: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

// A disabled rising edge leaves Q unchanged.
    check_hold_on_disable: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

// Enabled new data must change Q on the next sampled cycle.
    check_change_on_new_enabled_data: assert property (
        @(posedge C) (E && (D != Q)) |=> (Q != $past(Q))
    );

// Enabled same data must leave Q unchanged.
    check_no_change_on_same_enabled_data: assert property (
        @(posedge C) (E && (D == Q)) |=> (Q == $past(Q))
    );

endmodule

rtl:
module shift_reg (
    input CLK,
    input RST,
    input LD,
    input [3:0] D,
    output [3:0] OUT
);

reg [3:0] reg1, reg2, reg3, reg4;

always @(posedge CLK) begin
    if (RST) begin
        reg1 <= 4'b0;
        reg2 <= 4'b0;
        reg3 <= 4'b0;
        reg4 <= 4'b0;
    end else if (LD) begin
        reg1 <= D;
        reg2 <= reg1;
        reg3 <= reg2;
        reg4 <= reg3;
    end else begin
        reg1 <= reg2;
        reg2 <= reg3;
        reg3 <= reg4;
        reg4 <= reg4;
    end
end

assign OUT = reg4;

endmodule

sva:
module shift_reg_sva (
    input logic       CLK,
    input logic       RST,
    input logic       LD,
    input logic [3:0] D,
    input logic [3:0] OUT
);

// When load is low, the output holds its value.
    check_out_holds_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST)
        !LD |=> (OUT == $past(OUT))
    );

endmodule

rtl:
module sky130_fd_sc_ls__ha (
    COUT,
    SUM ,
    A   ,
    B
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;

    wire and0_out_COUT;
    wire xor0_out_SUM ;

    and and0 (and0_out_COUT, A, B           );
    buf buf0 (COUT         , and0_out_COUT  );
    xor xor0 (xor0_out_SUM , B, A           );
    buf buf1 (SUM          , xor0_out_SUM   );

endmodule

sva:
module sky130_fd_sc_ls__ha_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B
);

// Carry output matches the input AND.
    check_cout_is_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// Sum output matches the input XOR.
    check_sum_is_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// 0 + 0 produces zero sum and zero carry.
    check_zero_zero_case: assert property (
        @(posedge clk) (!A && !B) |-> (!SUM && !COUT)
    );

// 1 + 0 produces sum with no carry.
    check_one_zero_case: assert property (
        @(posedge clk) (A && !B) |-> (SUM && !COUT)
    );

// 0 + 1 produces sum with no carry.
    check_zero_one_case: assert property (
        @(posedge clk) (!A && B) |-> (SUM && !COUT)
    );

// 1 + 1 produces carry with no sum.
    check_one_one_case: assert property (
        @(posedge clk) (A && B) |-> (!SUM && COUT)
    );

endmodule

