rtl:
module mux_2_1(input sel, input in0, input in1, output out);
    wire not_sel;
    wire and_0;
    wire and_1;

    not (not_sel, sel);

    and (and_0, in0, not_sel);

    and (and_1, in1, sel);

    assign out = and_0 | and_1;
endmodule

sva:
module mux_2_1_sva (
    input logic clk,
    input logic sel,
    input logic in0,
    input logic in1,
    input logic out
);

// Out matches the implemented mux equation.
    check_mux_boolean_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        out == ((in0 & ~sel) | (in1 & sel))
    );

// When sel is low, out follows in0.
    check_sel_low_routes_in0: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b0) |-> (out == in0)
    );

// When sel is high, out follows in1.
    check_sel_high_routes_in1: assert property (
        @(posedge clk) disable iff (1'b0)
        (sel == 1'b1) |-> (out == in1)
    );

// If both inputs are low, out is low.
    check_both_inputs_low_drive_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b0) |-> (out == 1'b0)
    );

// If both inputs are high, out is high.
    check_both_inputs_high_drive_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b1) |-> (out == 1'b1)
    );

// With in0 high and in1 low, out is the inverse of sel.
    check_in0_high_in1_low_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b1 && in1 == 1'b0) |-> (out == ~sel)
    );

// With in0 low and in1 high, out matches sel.
    check_in0_low_in1_high_case: assert property (
        @(posedge clk) disable iff (1'b0)
        (in0 == 1'b0 && in1 == 1'b1) |-> (out == sel)
    );

endmodule

rtl:
module adder4 (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] temp_sum;
  wire c1, c2, c3;

  // First stage of addition
  full_adder fa1(.a(a[0]), .b(b[0]), .cin(cin), .sum(temp_sum[0]), .cout(c1));

  // Second stage of addition
  full_adder fa2(.a(a[1]), .b(b[1]), .cin(c1), .sum(temp_sum[1]), .cout(c2));

  // Third stage of addition
  full_adder fa3(.a(a[2]), .b(b[2]), .cin(c2), .sum(temp_sum[2]), .cout(c3));

  // Fourth stage of addition
  full_adder fa4(.a(a[3]), .b(b[3]), .cin(c3), .sum(temp_sum[3]), .cout(cout));

  assign sum = temp_sum;

endmodule

module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (cin & a) | (cin & b);

endmodule

sva:
module adder4_assertions (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

// The 5-bit result matches unsigned addition of a, b, and cin.
    check_total_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Sum bit 0 matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == fa_sum(a[0], b[0], cin)
    );

// Sum bit 1 matches the ripple carry from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == fa_sum(a[1], b[1], fa_cout(a[0], b[0], cin))
    );

// Sum bit 2 matches the ripple carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == fa_sum(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin)))
    );

// Sum bit 3 matches the ripple carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == fa_sum(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Carry out matches the final ripple-carry stage.
    check_cout_chain: assert property (
        @(posedge clk) cout == fa_cout(a[3], b[3], fa_cout(a[2], b[2], fa_cout(a[1], b[1], fa_cout(a[0], b[0], cin))))
    );

// Adding zero with cin low passes a through unchanged.
    check_passthrough_a: assert property (
        @(posedge clk) (b == 4'h0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with cin low passes b through unchanged.
    check_passthrough_b: assert property (
        @(posedge clk) (a == 4'h0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// Zero plus zero produces cin in the LSB with no carry out.
    check_zero_plus_cin: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0) |-> (sum == {3'b000, cin} && cout == 1'b0)
    );

endmodule

rtl:
module logic_module (
    A,
    B,
    C,
    D,
    E,
    F,
    G,
    H,
    X
);

    input A;
    input B;
    input C;
    input D;
    input E;
    input F;
    input G;
    input H;
    output X;

    wire and0_out;
    wire or0_out;
    wire and1_out;
    wire or1_out;

    and and0 (and0_out, A, B);
    or or0 (or0_out, C, D);
    and and1 (and1_out, E, F);
    or or1 (or1_out, G, H);

    assign X = (and0_out || or0_out || !and1_out || !or1_out);

endmodule

sva:
module logic_module_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F,
    input logic G,
    input logic H,
    input logic X
);

// X matches the RTL combinational equation.
    check_x_matches_rtl: assert property (
        @(posedge clk)
        X == ((A && B) || (C || D) || !(E && F) || !(G || H))
    );

// A and B both high force X high.
    check_x_high_when_ab_high: assert property (
        @(posedge clk)
        (A && B) |-> X
    );

// Either C or D high forces X high.
    check_x_high_when_cd_high: assert property (
        @(posedge clk)
        (C || D) |-> X
    );

// If E and F are not both high, X must be high.
    check_x_high_when_ef_not_both_high: assert property (
        @(posedge clk)
        !(E && F) |-> X
    );

// If G and H are both low, X must be high.
    check_x_high_when_gh_both_low: assert property (
        @(posedge clk)
        !(G || H) |-> X
    );

// X low requires all four RTL terms to be false.
    check_x_low_implies_false_terms: assert property (
        @(posedge clk)
        !X |-> (!(A && B) && !(C || D) && (E && F) && (G || H))
    );

// If all four RTL terms are false, X must be low.
    check_x_low_when_false_terms: assert property (
        @(posedge clk)
        (!(A && B) && !(C || D) && (E && F) && (G || H)) |-> !X
    );

endmodule

rtl:
module simple_calculator(
    input signed [7:0] a, b,
    output reg signed [7:0] add_out, sub_out, mul_out, div_out,
    input [1:0] op
);

    always @ (a, b, op) begin
        case (op)
            2'b00: begin // addition
                add_out <= a + b;
                sub_out <= 0;
                mul_out <= 0;
                div_out <= 0;
            end
            2'b01: begin // subtraction
                add_out <= 0;
                sub_out <= a - b;
                mul_out <= 0;
                div_out <= 0;
            end
            2'b10: begin // multiplication
                add_out <= 0;
                sub_out <= 0;
                mul_out <= a * b;
                div_out <= 0;
            end
            2'b11: begin // division
                add_out <= 0;
                sub_out <= 0;
                mul_out <= 0;
                div_out <= a / b;
            end
        endcase
    end

endmodule

sva:
module simple_calculator_sva (
    input logic clk,
    input logic signed [7:0] a,
    input logic signed [7:0] b,
    input logic signed [7:0] add_out,
    input logic signed [7:0] sub_out,
    input logic signed [7:0] mul_out,
    input logic signed [7:0] div_out,
