);

// Addition mode computes the sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((add_out == s8_t'(a + b)) &&
                           (sub_out == 8'sd0) &&
                           (mul_out == 8'sd0) &&
                           (div_out == 8'sd0))
