rtl:
module xor_gate( input a, input b, output y );
  wire w1, w2, w3, w4;

  nand n1(w1, a, b);
  nand n2(w2, a, w1);
  nand n3(w3, b, w1);
  nand n4(y, w2, w3);

endmodule

sva:
module xor_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
