module comparator(input [3:0] A, B, C, D, output EQ, GT);

  wire a_greater_b, c_greater_d;

  assign a_greater_b = (A > B);
  assign c_greater_d = (C > D);

  assign EQ = (A == B) && (B == C) && (C == D);

  assign GT = (a_greater_b || ((A == B) && c_greater_d));

endmodule

sva:
module comparator_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic       EQ,
    input logic       GT
);

// EQ matches the all-inputs-equal comparison.
    check_eq_definition: assert property (
        @(posedge clk) EQ == ((A == B) && (B == C) && (C == D))
    );

// GT matches the comparator decision logic.
    check_gt_definition: assert property (
        @(posedge clk) GT == ((A > B) || ((A == B) && (C > D)))
    );

// Equal inputs force GT low.
    check_eq_implies_not_gt: assert property (
        @(posedge clk) EQ |-> !GT
    );

// A greater than B forces GT high.
    check_a_greater_b_sets_gt: assert property (
        @(posedge clk) (A > B) |-> GT
    );

// A less than B forces GT low.
    check_a_less_b_clears_gt: assert property (
        @(posedge clk) (A < B) |-> !GT
    );

// With A tied to B, C greater than D forces GT high.
    check_tie_breaker_sets_gt: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> GT
    );

// With A tied to B, C not greater than D forces GT low.
    check_tie_breaker_clears_gt: assert property (
        @(posedge clk) ((A == B) && (C <= D)) |-> !GT
    );

// When A equals B, GT can only come from C greater than D.
    check_gt_with_equal_ab_requires_c_greater_d: assert property (
        @(posedge clk) (GT && (A == B)) |-> (C > D)
    );

// When A differs from B, GT can only come from A greater than B.
    check_gt_with_unequal_ab_requires_a_greater_b: assert property (
        @(posedge clk) (GT && (A != B)) |-> (A > B)
    );

endmodule

rtl:
module sequence_counter(
  input slowest_sync_clk,
  input lpf_int,
  output reg Core,
  output reg bsr,
  output reg pr
);

  reg [31:0] cnt_100M = 0;
  reg [7:0] cnt_core = 0;
  reg [5:0] cnt_bsr = 0;

  always @(posedge slowest_sync_clk) begin
    cnt_100M <= cnt_100M + 1;
    if (cnt_100M == 100_000_000) begin
      cnt_100M <= 0;
      Core <= 1;
    end else begin
      Core <= 0;
    end
  end

  always @(posedge lpf_int) begin
    if (Core) begin
      cnt_core <= cnt_core + 1;
      if (cnt_core == 2**8) begin
        cnt_core <= 0;
        bsr <= 1;
      end else begin
        bsr <= 0;
      end
    end else begin
      bsr <= 0;
    end
  end

  always @(posedge lpf_int) begin
    if (bsr) begin
      cnt_bsr <= cnt_bsr + 1;
      if (cnt_bsr == 2**6) begin
        cnt_bsr <= 0;
        pr <= 1;
      end else begin
        pr <= 0;
      end
    end else begin
      pr <= 0;
    end
  end

endmodule

sva:
module sequence_counter_sva (
