        max >= c
    );

// max is never smaller than d.
    check_max_ge_d: assert property (
        @(posedge clk)
        max >= d
    );

// max must equal one of the four inputs.
    check_max_matches_an_input: assert property (
        @(posedge clk)
        (max == a) || (max == b) || (max == c) || (max == d)
    );

// If a is at least as large as all others, max equals a.
    check_a_is_max_value: assert property (
        @(posedge clk)
        ((a >= b) && (a >= c) && (a >= d)) |-> (max == a)
    );

// If b is at least as large as all others, max equals b.
    check_b_is_max_value: assert property (
        @(posedge clk)
        ((b >= a) && (b >= c) && (b >= d)) |-> (max == b)
    );

// If c is at least as large as all others, max equals c.
    check_c_is_max_value: assert property (
        @(posedge clk)
        ((c >= a) && (c >= b) && (c >= d)) |-> (max == c)
    );

// If d is at least as large as all others, max equals d.
    check_d_is_max_value: assert property (
        @(posedge clk)
        ((d >= a) && (d >= b) && (d >= c)) |-> (max == d)
    );

endmodule

rtl:
module sync_counter(clk, rst, load, data, count);
    input wire clk, rst, load;
    input wire [3:0] data;
    output reg [3:0] count;

    always @(posedge clk or posedge rst)
    begin
        if (rst) begin
            count <= 0;
        end
        else if (load) begin
            count <= data;
        end
        else begin
            count <= count + 1;
        end
    end
endmodule

sva:
module sync_counter_sva (
    input logic clk,
    input logic rst,
    input logic load,
    input logic [3:0] data,
    input logic [3:0] count
);

// Reset forces the counter output to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |-> (count == 4'd0)
    );

// When load is asserted, count updates with data on the next clock.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (rst) load |=> (count == $past(data))
    );

// When load is deasserted, count increments by one on the next clock.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst) !load |=> (count == ($past(count) + 4'd1))
    );

// Incrementing from 4'hF wraps the 4-bit counter back to zero.
    check_wraps_after_max: assert property (
        @(posedge clk) disable iff (rst) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && load) |-> (count == 4'd0)
    );

endmodule

rtl:
module top_module ( 
    input wire [3:0] in1,
    input wire [3:0] in2,
    output wire [3:0] out,
    output wire [3:0] max_out );

    // Adder module to calculate the sum of in1 and in2
    // The sum is stored in the variable 'sum'
    wire [3:0] sum;
    assign sum = in1 + in2;

    // Comparator module to calculate the maximum value between out and sum
    // The maximum value is stored in the variable 'max_value'
    wire [3:0] max_value;
    assign max_value = (out > sum) ? out : sum;

    // Assigning the sum to the out port
    assign out = sum;

    // Assigning the maximum value to the max_out port
    assign max_out = max_value;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] out,
    input logic [3:0] max_out
);

// out is the 4-bit sum of in1 and in2.
    check_out_matches_sum: assert property (
        @(posedge clk) out == (in1 + in2)
    );

// max_out follows the RTL max expression using out and the sum.
    check_max_out_matches_rtl_max_expr: assert property (
        @(posedge clk) max_out == ((out > (in1 + in2)) ? out : (in1 + in2))
    );

// Since out is assigned from the sum, max_out must equal out.
    check_max_out_equals_out: assert property (
        @(posedge clk) max_out == out
    );

// max_out also equals the computed 4-bit sum.
    check_max_out_matches_sum: assert property (
        @(posedge clk) max_out == (in1 + in2)
    );

endmodule

