module reverse_bit_order(
    input [99:0] in,
    input clk,
    output [99:0] out
);

reg [99:0] shift_reg;
wire [99:0] reversed;

assign reversed[0] = shift_reg[99];

genvar i;
generate
    for (i = 1; i < 100; i = i + 1) begin : SHIFT_LOOP
        assign reversed[i] = shift_reg[99-i];
    end
endgenerate

assign out = reversed;

always @(posedge clk) begin
    shift_reg <= {shift_reg[98:0], in[0]};
end

endmodule

sva:
module reverse_bit_order_sva (
    input logic [99:0] in,
    input logic        clk,
    input logic [99:0] out
);

// The output vector updates as a shift register driven only by the previous in[0].
    check_output_vector_update: assert property (
        @(posedge clk) 1'b1 |=> out == { $past(in[0]), $past(out[99:1]) }
    );

// The output MSB captures the previous cycle value of in[0].
    check_output_msb_from_input0: assert property (
        @(posedge clk) 1'b1 |=> out[99] == $past(in[0])
    );

// The lower 99 output bits shift from the previous cycle's higher output bits.
    check_output_lower_bits_shift: assert property (
        @(posedge clk) 1'b1 |=> out[98:0] == $past(out[99:1])
    );

endmodule

module AND_32bit_sva (
    input logic        clk,
    input logic [31:0] out,
    input logic [31:0] A,
    input logic [31:0] B
);

// RTL has no clock or reset; clk is an external sampling clock.

    // Output equals the bitwise AND of the two inputs.
    check_out_matches_bitwise_and: assert property (
        @(posedge clk) out == (A & B)
    );

// A value of zero forces the output to zero.
    check_zero_a_forces_zero_out: assert property (
        @(posedge clk) (A == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// B value of zero forces the output to zero.
    check_zero_b_forces_zero_out: assert property (
        @(posedge clk) (B == 32'h0000_0000) |-> (out == 32'h0000_0000)
    );

// All ones on A makes the output follow B.
    check_all_ones_a_passes_b: assert property (
        @(posedge clk) (A == 32'hFFFF_FFFF) |-> (out == B)
    );

// All ones on B makes the output follow A.
    check_all_ones_b_passes_a: assert property (
        @(posedge clk) (B == 32'hFFFF_FFFF) |-> (out == A)
    );

// Any high output bit must also be high in A.
    check_output_ones_subset_of_a: assert property (
        @(posedge clk) ((out & ~A) == 32'h0000_0000)
    );

// Any high output bit must also be high in B.
    check_output_ones_subset_of_b: assert property (
        @(posedge clk) ((out & ~B) == 32'h0000_0000)
    );

// Equal inputs pass through unchanged to the output.
    check_equal_inputs_pass_through: assert property (
        @(posedge clk) (A == B) |-> (out == A)
    );

endmodule

rtl:
module vga_color_generator (
    input clk,
    input rst,
    input [9:0] x,
    input [9:0] y,
    input hsync,
    input vsync,
    output reg [7:0] r,
    output reg [7:0] g,
    output reg [7:0] b
);

reg [9:0] h_count;
reg [9:0] v_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        h_count <= 10'h0;
        v_count <= 10'h0;
    end else begin
        if (hsync == 0) begin
            if (h_count == 799) begin
                h_count <= 10'h0;
                if (vsync == 0) begin
                    if (v_count == 524) begin
                        v_count <= 10'h0;
                    end else begin
                        v_count <= v_count + 1;
                    end
                end
            end else begin
                h_count <= h_count + 1;
            end
        end
    end
end

reg [7:0] color;

always @(*) begin
    if (h_count < 8 || h_count >= 792 || v_count < 8 || v_count >= 488) begin
        color = 8'h0;
    end else if (h_count < 648) begin
        color = {8'h0, 8'h0, h_count[5:0]};
    end else begin
        color = {8'h0, 8'h0, 8'hff - (h_count[5:0] - 8'h8)};
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        r <= 8'h0;
        g <= 8'h0;
        b <= 8'h0;
    end else begin
        if (hsync == 0 && vsync == 0) begin
            r <= color;
            g <= color;
            b <= color;
        end else begin
            r <= 8'h0;
            g <= 8'h0;
            b <= 8'h0;
        end
    end
end

endmodule

module memory_module(
    input [4:0] A1ADDR,
    input A1DATA,
    input A1EN,
    input CLK1,
    input [4:0] B1ADDR,
    output B1DATA
);

reg [31:0] mem = 32'b0;

`ifdef cyclonev
specify
    $setup(A1ADDR, posedge CLK1, 86);
    $setup(A1DATA, posedge CLK1, 86);
    $setup(A1EN, posedge CLK1, 86);

    (B1ADDR[0] => B1DATA) = 487;
    (B1ADDR[1] => B1DATA) = 475;
    (B1ADDR[2] => B1DATA) = 382;
    (B1ADDR[3] => B1DATA) = 284;
    (B1ADDR[4] => B1DATA) = 96;
endspecify
`endif
`ifdef arriav
specify
    $setup(A1ADDR, posedge CLK1, 62);
    $setup(A1DATA, posedge CLK1, 62);
    $setup(A1EN, posedge CLK1, 62);

    (B1ADDR[0] => B1DATA) = 370;
    (B1ADDR[1] => B1DATA) = 292;
    (B1ADDR[2] => B1DATA) = 218;
    (B1ADDR[3] => B1DATA) = 74;
    (B1ADDR[4] => B1DATA) = 177;
endspecify
`endif
`ifdef cyclone10gx
// TODO: Cyclone 10 GX timings; the below timings are for Cyclone V
specify
    $setup(A1ADDR, posedge CLK1, 86);
    $setup(A1DATA, posedge CLK1, 86);
    $setup(A1EN, posedge CLK1, 86);

    (B1ADDR[0] => B1DATA) = 487;
    (B1ADDR[1] => B1DATA) = 475;
    (B1ADDR[2] => B1DATA) = 382;
    (B1ADDR[3] => B1DATA) = 284;
    (B1ADDR[4] => B1DATA) = 96;
endspecify
`endif

always @(posedge CLK1)
    if (A1EN) mem[A1ADDR] <= A1DATA;

wire B1DATA_wire;
assign B1DATA_wire = mem[B1ADDR];
assign B1DATA = B1DATA_wire;

endmodule

sva:
module memory_module_assertions (
    input logic [4:0] A1ADDR,
    input logic       A1DATA,
    input logic       A1EN,
    input logic       CLK1,
    input logic [4:0] B1ADDR,
    input logic       B1DATA,
    input logic [31:0] mem
);

// Clock is CLK1; there is no reset in the RTL.

    // Read data always reflects the selected memory bit.
    check_read_data_matches_mem: assert property (
        @(posedge CLK1) B1DATA == mem[B1ADDR]
    );

// With write enable low, the memory contents hold.
    check_no_write_holds_mem: assert property (
        @(posedge CLK1) !A1EN |=> $stable(mem)
    );

// A write updates memory exactly at the addressed bit.
    check_write_updates_full_mem_state: assert property (
        @(posedge CLK1)
        A1EN |=> mem == (($past(mem) & ~(32'h1 << $past(A1ADDR))) |
                         ({31'b0, $past(A1DATA)} << $past(A1ADDR)))
    );

// A write stores A1DATA into the addressed location.
    check_write_updates_addressed_bit: assert property (
        @(posedge CLK1) A1EN |=> mem[$past(A1ADDR)] == $past(A1DATA)
    );

// A write does not change any unaddressed memory bits.
    check_write_preserves_unaddressed_bits: assert property (
        @(posedge CLK1)
        A1EN |=> (((mem ^ $past(mem)) & ~(32'h1 << $past(A1ADDR))) == 32'h0)
    );

// Writing the existing value leaves memory unchanged.
    check_same_value_write_keeps_mem_stable: assert property (
        @(posedge CLK1) (A1EN && (A1DATA == mem[A1ADDR])) |=> $stable(mem)
    );

// A subsequent read of the written address returns the stored data.
    check_read_after_write_same_address: assert property (
        @(posedge CLK1)
        A1EN |=> ((B1ADDR != $past(A1ADDR)) || (B1DATA == $past(A1DATA)))
    );

endmodule

rtl:
module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output reg [7:0] result
);

    always @(*) begin
        case(op)
            2'b00: result = A + B;
            2'b01: result = A - B;
            2'b10: result = A * B;
            2'b11: begin
                if(B == 0) result = 0;
                else result = A / B;
            end
            default: result = 0;
        endcase
    end

endmodule

sva:
module calculator_sva(
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] result
);

// Addition opcode returns A + B, truncated to 8 bits.
    check_add_operation: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((A + B) & 8'hff))
    );

// Subtraction opcode returns A - B, truncated to 8 bits.
    check_sub_operation: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((A - B) & 8'hff))
    );

// Division by zero forces the result to zero.
    check_div_by_zero: assert property (
        @(posedge clk) (op == 2'b11 && B == 8'h00) |-> (result == 8'h00)
    );

